import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
FILES=sorted((ROOT/'questions/science').glob('question-science-content-ab-iv-4-*.json'),key=lambda p:int(p.stem.rsplit('-',1)[1]))
ITEMS=[
('純物質定義','下列哪一項是純物質？',['空氣','食鹽水','蒸餾水','含砂糖的茶'],'C','蒸餾水只含水這一種物質，組成固定，屬純物質。'),
('混合物判定','下列哪一項屬於混合物？',['氧氣','金','二氧化碳','空氣'],'D','空氣由氮氣、氧氣等多種物質混合而成，比例可變，屬混合物。'),
('溶液分類','食鹽完全溶於水形成透明食鹽水，應分類為？',['元素','化合物','均勻混合物','單一純物質'],'C','食鹽水同時含水與食鹽，雖均勻仍是由多種物質組成的均勻混合物。'),
('均勻與不均勻','水和沙混合後靜置，沙沉在杯底。此系統屬於？',['均勻混合物','不均勻混合物','元素','化合物'],'B','不同位置可觀察到組成不同，水沙混合物屬不均勻混合物。'),
('分離方法','要從食鹽水取得食鹽固體，最適合使用哪種方法？',['過濾','蒸發結晶','磁鐵吸引','用篩網分離'],'B','食鹽已溶解，不能用過濾；除去水分可利用蒸發結晶取得食鹽。'),
('混合物特徵','混合物與化合物的主要差異之一是？',['混合物各成分仍保有原本性質','混合物一定只有兩種成分','化合物可以用過濾分離','混合物一定有固定熔點'],'A','混合物成分只是混合，通常仍保有原本性質，且比例可變。'),
('純物質組成','某樣品每次分析都含固定比例的氫與氧，且可化學分解成兩種元素，最合理分類是？',['元素','化合物','不均勻混合物','溶液'],'B','由兩種元素固定比例結合且可化學分解，符合化合物定義。'),
('物理分離','鐵屑與砂子的混合物可用磁鐵分離，這說明？',['混合物成分保有可利用的物理性質','鐵屑與砂子已生成新化合物','磁鐵能分解原子','所有混合物都能磁選'],'A','磁性差異是成分保留的物理性質，利用它即可物理分離。'),
('蒸餾用途','蒸餾可把溶液中的水分離出來，主要利用不同成分的哪項差異？',['沸點','顏色必定不同','原子序','磁性一定不同'],'A','蒸餾利用成分沸點不同，先後汽化、冷凝而分離。'),
('分類判準','判斷樣品是純物質或混合物時，最有用的初步問題是？',['組成是否固定且只含一種物質','樣品顏色是否漂亮','容器是否透明','取樣時間是否相同'],'A','純物質組成固定且只含一種物質；混合物含多種物質且比例可變。'),
]
for p,(topic,prompt,opts,ans,ex) in zip(FILES,ITEMS):
 d=json.loads(p.read_text()); d['prompt']=prompt; d['options']=[{'id':chr(65+i),'text':t} for i,t in enumerate(opts)]; d['answer']={'value':ans,'explanation':ex}; d['solutionStrategy']=f'先判斷樣品成分數量與組成是否固定，再選擇適合的分離方法；本題聚焦於{topic}。'; d['solutionSteps']=['先列出樣品中可能存在的物質。','檢查組成是否固定、各成分是否仍保有原性質，以及能否用物理方法分離。',f'依純物質／混合物定義或分離原理，得到答案{ans}。',f'回看解析：{ex}','最後避免把均勻外觀誤判成純物質，也避免把化學分解和物理分離混為一談。']; d['reviewStatus']='draft'; d['updatedAt']='2026-09-08'; d['provenance']['authoringNote']='依官方課綱與公開會考、公立國中試題所呈現的純物質／混合物分類與分離能力方向獨立改寫；未複製原題文字、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'; p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
